import {seasonMeta,PASS_PRICE,seasonState} from './season.js';
import {ZIRVE_PATHS,zirveState,zirveProgress,zirveMissions,zirveRewards} from './zirve-yolu.js';
export function zirveYoluView({S,esc,fmt}){
 const p=S.profile,now=p?.serverNow||Date.now(),meta=seasonMeta(now),state=p?zirveState(p,now):null,paid=p?seasonState(p,now).paid:false,level=p?zirveProgress(p,now):0,path=state?.path;
 return `<section class="zirve-route"><header class="route-hero"><small>${meta.number}. SEZON · 30 GÜN</small><h1>Zirve Yolu</h1><p>Tarzını seç. Görevleri tamamla. Ödülüne sen karar ver.</p><b data-season-countdown></b><div class="route-status"><span>${path?esc(ZIRVE_PATHS[path].name)+' Yolu':'Üç yoldan biri seni bekliyor'}</span><strong>${level} / 20 kademe</strong></div>${!p?'<button class="primary" data-page="auth">Giriş yap</button>':paid?'<span class="route-ticket">✓ Bu sezonun bileti açık</span>':`<button class="primary" data-act="pass">${fmt(PASS_PRICE)} Gold · Sezon biletini aç</button>`}<p class="subtle">Seçtiğin yol sezon boyunca sabit kalır. Eski koleksiyonun korunur.</p></header><div class="route-paths">${Object.entries(ZIRVE_PATHS).map(([id,v])=>`<article class="route-path ${path===id?'selected':''}" style="--route-color:${v.color}"><span>${v.icon}</span><h2>${esc(v.name)}</h2><p>${esc(v.description)}</p><button data-act="zirveChoose" data-value="${id}" ${!p||path?'disabled':''}>${path===id?'✓ Seçili yol':path?'Diğer sezon':'Bu yolu seç'}</button></article>`).join('')}</div>${path?`<div class="route-progress"><progress max="20" value="${level}"></progress><b>${level} / 20</b></div><div class="route-missions">${zirveMissions(path).map(m=>{const claimed=state.claimed[m.level],ready=level>=m.level,current=Math.min(seasonState(p,now).stats[m.metric]||0,m.target),rewards=zirveRewards(path,m.level,now);return `<article class="route-mission ${claimed?'claimed':ready?'ready':''}"><div class="route-level">${String(m.level).padStart(2,'0')}</div><div><h3>${esc(m.label)}</h3><progress max="${m.target}" value="${current}"></progress><small>${fmt(current)} / ${fmt(m.target)}${m.level%5===0?' · Üç ödülden birini seç':''}</small>${m.level===20?`<p class="route-title">✦ ${meta.number}. Sezon ${path==='avci'?'Avcısı':path==='sampiyon'?'Şampiyonu':'Klan Öncüsü'} · Kalıcı unvan</p>`:''}</div><div class="route-rewards">${rewards.map(r=>`<button data-act="zirveClaim" data-level="${m.level}" data-value="${r.id}" ${!paid||!ready||claimed?'disabled':''}>${claimed===r.id?'✓ ':''}${esc(r.name)}</button>`).join('')}${claimed?'<small>Seçim kaydedildi</small>':''}</div></article>`}).join('')}</div>`:'<div class="route-empty"><h2>20 kademe, sana ait bir yol</h2><p>Her beş kademede Gold, Premium veya özel sezon skini arasından seçim yap. Son kademede sezon numaralı kalıcı unvanını kazan.</p></div>'}<footer><button data-page="inventory">Kalıcı koleksiyonum →</button><button data-page="seasonleaders">Sezon sıralaması →</button></footer></section>`;
}
